cat > src/lib/billing-lock.ts <<'EOF'
/**
 * The read-only lock for a workspace whose subscription is not in good
 * standing.
 *
 * `lockReasonFor()` is the single statement of the rule and is pure; the
 * service layer feeds it the stored subscription at the moment of each write
 * (`assertWorkspaceWritable`), and the summaries feed it to report the lock.
 * `WorkspaceLockedError` is what a refused write throws — `toAppError()` maps
 * it onto `plan_limit_exceeded`, since a plan choice is the way out.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

const LOCK_MESSAGES: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "This workspace is read-only until the past-due payment is settled.",
  canceled: "This workspace is read-only because its subscription was canceled.",
  trial_ended: "This workspace is read-only because its trial has ended.",
};

/** Raised when a write reaches a workspace that is currently locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(LOCK_MESSAGES[reason]);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * `null` means writable. A workspace with no subscription row, or an `active`
 * one, is writable; every other status locks it, some only from a moment on:
 *
 * - `trialing` locks once the period end is reached (at or after it);
 * - `canceled` locks once `cancelAt` is reached, and a canceled subscription
 *   with no `cancelAt` counts as canceled already.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null || reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
  }
}

function reached(stamp: string, now: Date): boolean {
  return now.getTime() >= new Date(stamp).getTime();
}
EOF

