/** The read-only lock rule: which subscriptions lock a workspace, and when. */
import { describe, expect, it } from "vitest";
import { WorkspaceLockedError, lockReasonFor } from "@/lib/billing-lock";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";
import { ORG_A } from "../helpers/factories";

const NOW = new Date("2026-06-15T12:00:00.000Z");

function stamp(offsetMs: number): IsoTimestamp {
  return new Date(NOW.getTime() + offsetMs).toISOString() as IsoTimestamp;
}

function subscription(
  status: SubscriptionStatus,
  overrides: Partial<Subscription> = {},
): Subscription {
  return {
    id: "sub-1" as Subscription["id"],
    orgId: ORG_A,
    plan: "growth",
    interval: "monthly",
    status,
    seats: 5,
    currentPeriodStart: stamp(-14 * 86_400_000),
    currentPeriodEnd: stamp(14 * 86_400_000),
    cancelAt: null,
    createdAt: stamp(-14 * 86_400_000),
    updatedAt: stamp(-14 * 86_400_000),
    ...overrides,
  };
}

describe("lib/billing-lock", () => {
  it("leaves a workspace without a subscription writable", () => {
    expect(lockReasonFor(null, NOW)).toBeNull();
  });

  it("leaves an active subscription writable", () => {
    expect(lockReasonFor(subscription("active"), NOW)).toBeNull();
    expect(
      lockReasonFor(
        subscription("active", { currentPeriodEnd: stamp(-86_400_000) }),
        NOW,
      ),
    ).toBeNull();
  });

  it("locks a past-due subscription", () => {
    expect(lockReasonFor(subscription("past_due"), NOW)).toBe("past_due");
  });

  it("locks a trial from the moment its period end is reached", () => {
    const before = subscription("trialing", { currentPeriodEnd: stamp(1) });
    const at = subscription("trialing", { currentPeriodEnd: stamp(0) });
    const after = subscription("trialing", { currentPeriodEnd: stamp(-1) });

    expect(lockReasonFor(before, NOW)).toBeNull();
    expect(lockReasonFor(at, NOW)).toBe("trial_ended");
    expect(lockReasonFor(after, NOW)).toBe("trial_ended");
  });

  it("keeps a canceled subscription writable until its cancellation date", () => {
    const scheduled = subscription("canceled", { cancelAt: stamp(1) });
    const reached = subscription("canceled", { cancelAt: stamp(0) });
    const passed = subscription("canceled", { cancelAt: stamp(-1) });

    expect(lockReasonFor(scheduled, NOW)).toBeNull();
    expect(lockReasonFor(reached, NOW)).toBe("canceled");
    expect(lockReasonFor(passed, NOW)).toBe("canceled");
  });

  it("counts a canceled subscription without a cancellation date as canceled now", () => {
    expect(lockReasonFor(subscription("canceled", { cancelAt: null }), NOW)).toBe(
      "canceled",
    );
  });

  it("defaults `now` to the current time", () => {
    const ended = subscription("trialing", {
      currentPeriodEnd: "2000-01-01T00:00:00.000Z" as IsoTimestamp,
    });
    const running = subscription("trialing", {
      currentPeriodEnd: "2999-01-01T00:00:00.000Z" as IsoTimestamp,
    });

    expect(lockReasonFor(ended)).toBe("trial_ended");
    expect(lockReasonFor(running)).toBeNull();
  });

  it("carries the org and reason on the error", () => {
    const error = new WorkspaceLockedError(ORG_A, "past_due");

    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("plan_limit_exceeded");
    expect(error.orgId).toBe(ORG_A);
    expect(error.reason).toBe("past_due");
  });
});
EOF
