let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** Writes the stored subscription state directly, as billing would. */
function setSubscription(
  orgId: OrgId,
  patch: {
    status: SubscriptionStatus;
    currentPeriodEnd?: IsoTimestamp;
    cancelAt?: IsoTimestamp | null;
  },
): void {
  getDb().update(subscriptions).set(patch).where(eq(subscriptions.orgId, orgId)).run();
}

const DAY_MS = 86_400_000;

function daysFromNow(days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(Date.now() + days * DAY_MS));
}

async function expectLocked(
  attempt: Promise<unknown>,
  reason: WorkspaceLockReason,
): Promise<void> {
  const error = await attempt.then(
    () => null,
    (thrown: unknown) => thrown,
  );
  expect(error).toBeInstanceOf(WorkspaceLockedError);
  expect((error as WorkspaceLockedError).reason).toBe(reason);
}

describe("assertWorkspaceWritable", () => {
  it("passes for an active subscription and for a running trial", async () => {
    const free = await createTenant("lock-active", "free");
    const trial = await createTenant("lock-trial-running", "growth");

    await expect(billingService.assertWorkspaceWritable(free.org.id)).resolves.toBeUndefined();
    await expect(billingService.assertWorkspaceWritable(trial.org.id)).resolves.toBeUndefined();
  });

  it("passes for a workspace with no subscription row", async () => {
    const tenant = await createTenant("lock-no-subscription", "free");
    getDb().delete(subscriptions).where(eq(subscriptions.orgId, tenant.org.id)).run();

    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
  });

  it("judges the trial at the `now` it is given", async () => {
    const tenant = await createTenant("lock-trial-clock", "growth");
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    const periodEnd = new Date(subscription?.currentPeriodEnd ?? "");

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date(periodEnd.getTime() - 1)),
    ).resolves.toBeUndefined();
    await expectLocked(
      billingService.assertWorkspaceWritable(tenant.org.id, periodEnd),
      "trial_ended",
    );
  });

  it("locks past-due and canceled workspaces, honouring a scheduled cancellation", async () => {
    const pastDue = await createTenant("lock-past-due", "growth");
    setSubscription(pastDue.org.id, { status: "past_due" });
    await expectLocked(billingService.assertWorkspaceWritable(pastDue.org.id), "past_due");

    const scheduled = await createTenant("lock-cancel-later", "growth");
    setSubscription(scheduled.org.id, { status: "canceled", cancelAt: daysFromNow(5) });
    await expect(billingService.assertWorkspaceWritable(scheduled.org.id)).resolves.toBeUndefined();
    await expectLocked(
      billingService.assertWorkspaceWritable(scheduled.org.id, new Date(Date.now() + 6 * DAY_MS)),
      "canceled",
    );

    const undated = await createTenant("lock-cancel-undated", "growth");
    setSubscription(undated.org.id, { status: "canceled", cancelAt: null });
    await expectLocked(billingService.assertWorkspaceWritable(undated.org.id), "canceled");
  });
});

describe("a locked workspace", () => {
  /** Everything a write needs, created while the workspace was still writable. */
  async function prepare(slug: string) {
    const tenant = await createTenant(slug, "growth");
    const { org, project, actors, userIds } = tenant;

    const issue = await issueService.createIssue(
      actors.member,
      issueInput(org.id, project.id, { title: "Existing issue" }),
    );
    const comment = await commentService.createComment(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      body: "Existing comment",
      parentId: null,
      mentionedUserIds: [],
    });
    const label = await labelService.createLabel(actors.admin, {
      orgId: org.id,
      name: "existing",
      color: "#94a3b8",
      description: null,
    });
    const attachment = await attachmentService.addAttachment(actors.member, {
      orgId: org.id,
      issueId: issue.id,
      filename: "notes.txt",
      contentType: "text/plain",
      sizeBytes: 2048,
    });
    const archivedProject = await projectService.createProject(actors.admin, {
      orgId: org.id,
      name: "Old project",
      slug: "old-project",
      key: "OLD",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(actors.admin, {
      orgId: org.id,
      projectId: archivedProject.id,
      archiveIssues: true,
    });
    const invitation = await invitationService.inviteMember(actors.admin, {
      orgId: org.id,
      email: `resend@${slug}.test`,
      role: "member",
    });
    const webhook = await webhookService.createWebhook(actors.admin, {
      orgId: org.id,
      url: "https://hooks.example.com/taskflow",
      eventTypes: ["issue.created"],
    });
    const viewerMember = await memberRepo.findMember(org.id, userIds.viewer);
    if (!viewerMember) throw new Error("fixture has no viewer");

    return { tenant, issue, comment, label, attachment, archivedProject, invitation, webhook, viewerMember };
  }

  it("refuses every write with the reason, and writes and publishes nothing", async () => {
    const ctx = await prepare("lock-writes");
    const { tenant } = ctx;
    const { org, project, actors } = tenant;
    const { owner, admin, member } = actors;
    setSubscription(org.id, { status: "past_due" });

    const published: string[] = [];
    const offs: Unsubscribe[] = [
      subscribe("issue.created", () => void published.push("issue.created")),
      subscribe("issue.updated", () => void published.push("issue.updated")),
      subscribe("issue.status_changed", () => void published.push("issue.status_changed")),
      subscribe("issue.assigned", () => void published.push("issue.assigned")),
      subscribe("issue.archived", () => void published.push("issue.archived")),
      subscribe("comment.created", () => void published.push("comment.created")),
      subscribe("comment.deleted", () => void published.push("comment.deleted")),
      subscribe("project.created", () => void published.push("project.created")),
      subscribe("project.archived", () => void published.push("project.archived")),
      subscribe("project.restored", () => void published.push("project.restored")),
      subscribe("member.role_changed", () => void published.push("member.role_changed")),
      subscribe("member.removed", () => void published.push("member.removed")),
      subscribe("member.invited", () => void published.push("member.invited")),
      subscribe("flag.toggled", () => void published.push("flag.toggled")),
    ];
    const issuesBefore = (await issueRepo.listIssues({ orgId: org.id, limit: 100, cursor: null })).total;

    const writes: ReadonlyArray<readonly [string, () => Promise<unknown>]> = [
      ["createIssue", () => issueService.createIssue(member, issueInput(org.id, project.id))],
      ["updateIssue", () => issueService.updateIssue(member, { orgId: org.id, issueId: ctx.issue.id, title: "Renamed" })],
      ["changeIssueStatus", () => issueService.changeIssueStatus(member, { orgId: org.id, issueId: ctx.issue.id, status: "done" })],
      ["changeIssueStatus (no-op)", () => issueService.changeIssueStatus(member, { orgId: org.id, issueId: ctx.issue.id, status: ctx.issue.status })],
      ["moveIssue", () => issueService.moveIssue(member, { orgId: org.id, issueId: ctx.issue.id, toStatus: "in_progress", toIndex: 0 })],
      ["assignIssue", () => issueService.assignIssue(admin, { orgId: org.id, issueId: ctx.issue.id, assigneeId: tenant.userIds.member })],
      ["unassignIssue", () => issueService.assignIssue(admin, { orgId: org.id, issueId: ctx.issue.id, assigneeId: null })],
      ["archiveIssue", () => issueService.archiveIssue(admin, org.id, ctx.issue.id)],
      ["createComment", () => commentService.createComment(member, { orgId: org.id, issueId: ctx.issue.id, body: "Hi", parentId: null, mentionedUserIds: [] })],
      ["updateComment", () => commentService.updateComment(member, { orgId: org.id, commentId: ctx.comment.id, body: "Edited" })],
      ["deleteComment", () => commentService.deleteComment(member, { orgId: org.id, commentId: ctx.comment.id })],
      ["createProject", () => projectService.createProject(admin, { orgId: org.id, name: "Another", slug: "another", key: "ANO", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null })],
      ["updateProject", () => projectService.updateProject(admin, { orgId: org.id, projectId: project.id, name: "Renamed project" })],
      ["archiveProject", () => projectService.archiveProject(admin, { orgId: org.id, projectId: project.id, archiveIssues: true })],
      ["restoreProject", () => projectService.restoreProject(admin, org.id, ctx.archivedProject.id)],
      ["createLabel", () => labelService.createLabel(admin, { orgId: org.id, name: "fresh", color: "#94a3b8", description: null })],
      ["updateLabel", () => labelService.updateLabel(admin, { orgId: org.id, labelId: ctx.label.id, name: "renamed" })],
      ["deleteLabel", () => labelService.deleteLabel(admin, org.id, ctx.label.id)],
      ["addAttachment", () => attachmentService.addAttachment(member, { orgId: org.id, issueId: ctx.issue.id, filename: "more.txt", contentType: "text/plain", sizeBytes: 10 })],
      ["removeAttachment", () => attachmentService.removeAttachment(member, { orgId: org.id, attachmentId: ctx.attachment.id })],
      ["updateMemberRole", () => memberService.updateMemberRole(owner, { orgId: org.id, memberId: ctx.viewerMember.id, role: "member" })],
      ["removeMember", () => memberService.removeMember(owner, { orgId: org.id, memberId: ctx.viewerMember.id })],
      ["inviteMember", () => invitationService.inviteMember(admin, { orgId: org.id, email: "new@lock-writes.test", role: "member" })],
      ["revokeInvitation", () => invitationService.revokeInvitation(admin, ctx.invitation.id)],
      ["resendInvitation", () => invitationService.resendInvitation(admin, ctx.invitation.id)],
      ["updateOrganization", () => organizationService.updateOrganization(owner, { orgId: org.id, name: "Renamed org" })],
      ["toggleFlag", () => featureFlagService.toggleFlag(owner, { orgId: org.id, flag: "csv_export", enabled: true })],
      ["createWebhook", () => webhookService.createWebhook(admin, { orgId: org.id, url: "https://hooks.example.com/other", eventTypes: ["issue.created"] })],
      ["updateWebhook", () => webhookService.updateWebhook(admin, { orgId: org.id, webhookId: ctx.webhook.id as never, enabled: false })],
      ["deleteWebhook", () => webhookService.deleteWebhook(admin, { orgId: org.id, webhookId: ctx.webhook.id as never })],
    ];

    for (const [name, write] of writes) {
      await expectLocked(write(), "past_due").catch((cause: unknown) => {
        throw new Error(`${name} was not refused with WorkspaceLockedError`, { cause });
      });
    }

    for (const off of offs) off();

    expect(published).toEqual([]);
    const issuesAfter = (await issueRepo.listIssues({ orgId: org.id, limit: 100, cursor: null })).total;
    expect(issuesAfter).toBe(issuesBefore);
    await expect(issueRepo.findIssueById(org.id, ctx.issue.id)).resolves.toMatchObject({
      title: "Existing issue",
      archivedAt: null,
    });
    await expect(memberRepo.findMemberById(org.id, ctx.viewerMember.id)).resolves.toMatchObject({
      role: "viewer",
      archivedAt: null,
    });
    await expect(invitationRepo.listPendingInvitations(org.id)).resolves.toHaveLength(1);
  });

  it("leaves a pending invitation pending and creates no membership", async () => {
    const ctx = await prepare("lock-accept");
    const { org, actors } = ctx.tenant;
    const token = "c".repeat(32);
    await invitationRepo.insertInvitation(
      org.id,
      { orgId: org.id, email: "joiner@lock-accept.test", role: "member", expiresInDays: 14 },
      actors.admin.userId,
      hashToken(token),
    );
    const joiner = await userRepo.insertUser({
      email: "joiner@lock-accept.test",
      name: "Joiner",
      passwordHash: "seed",
    });
    const pendingBefore = await invitationRepo.countPendingInvitations(org.id);
    setSubscription(org.id, { status: "canceled", cancelAt: null });

    await expectLocked(invitationService.acceptInvitation(joiner.id, { token }), "canceled");

    await expect(invitationRepo.countPendingInvitations(org.id)).resolves.toBe(pendingBefore);
    await expect(memberRepo.findMember(org.id, joiner.id)).resolves.toBeNull();

    // Choosing a plan lifts the lock, and the same invitation is then accepted.
    await billingService.changePlan(actors.owner, { orgId: org.id, plan: "growth", interval: "monthly" });
    await expect(invitationService.acceptInvitation(joiner.id, { token })).resolves.toMatchObject({
      userId: joiner.id,
    });
  });

  it("still gives a caller who would be refused anyway the refusal they get today", async () => {
    const ctx = await prepare("lock-precedence");
    const { org, project, actors } = ctx.tenant;
    const other = await createTenant("lock-precedence-other", "growth");
    setSubscription(org.id, { status: "past_due" });

    await expect(
      issueService.createIssue(other.actors.member, issueInput(org.id, project.id)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      issueService.createIssue(actors.viewer, issueInput(org.id, project.id)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.removeMember(actors.member, { orgId: org.id, memberId: ctx.viewerMember.id }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      invitationService.inviteMember(actors.member, { orgId: org.id, email: "x@lock-precedence.test", role: "member" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      featureFlagService.toggleFlag(actors.member, { orgId: org.id, flag: "csv_export", enabled: true }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      invitationService.acceptInvitation(actors.member.userId, { token: "z".repeat(32) }),
    ).rejects.toThrow(/Invitation .* was not found/);
  });

  it("keeps reads working", async () => {
    const ctx = await prepare("lock-reads");
    const { org, project, actors } = ctx.tenant;
    setSubscription(org.id, { status: "past_due" });

    await expect(issueService.getIssue(actors.member, org.id, ctx.issue.id)).resolves.toBeDefined();
    await expect(
      issueService.listIssues(actors.member, { orgId: org.id, limit: 20, cursor: null }),
    ).resolves.toBeDefined();
    await expect(issueService.getBoard(actors.member, org.id, project.id)).resolves.toBeDefined();
    await expect(commentService.getThread(actors.member, org.id, ctx.issue.id)).resolves.toHaveLength(1);
    await expect(labelService.listLabels(actors.member, org.id)).resolves.toHaveLength(1);
    await expect(attachmentService.listAttachments(actors.member, org.id, ctx.issue.id)).resolves.toHaveLength(1);
    await expect(webhookService.listWebhooks(actors.admin, org.id)).resolves.toHaveLength(1);
    await expect(
      memberService.listMembers(actors.member, { orgId: org.id, limit: 20, cursor: null }),
    ).resolves.toBeDefined();
  });

  it("reports the lock in the billing and organization summaries", async () => {
    const tenant = await createTenant("lock-summaries", "growth");
    const { org, actors } = tenant;

    await expect(billingService.getBillingSummary(actors.owner, org.id)).resolves.toMatchObject({
      lockReason: null,
    });
    await expect(organizationService.getOrganizationSummary(actors.member, org.id)).resolves.toMatchObject({
      lockReason: null,
    });

    setSubscription(org.id, { status: "trialing", currentPeriodEnd: daysFromNow(-1) });

    await expect(billingService.getBillingSummary(actors.owner, org.id)).resolves.toMatchObject({
      lockReason: "trial_ended",
    });
    await expect(organizationService.getOrganizationSummary(actors.member, org.id)).resolves.toMatchObject({
      lockReason: "trial_ended",
    });
  });

  it("keeps billing working, and a plan change makes it writable again", async () => {
    const tenant = await createTenant("lock-billing", "growth");
    const { org, project, actors } = tenant;
    setSubscription(org.id, { status: "past_due" });

    await expect(billingService.getBillingSummary(actors.owner, org.id)).resolves.toBeDefined();
    await expect(billingService.updateSeats(actors.owner, { orgId: org.id, seats: 6 })).resolves.toMatchObject({
      seats: 6,
    });
    await expect(billingService.listInvoices(actors.owner, org.id)).resolves.toBeDefined();
    await expectLocked(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
      "past_due",
    );

    await billingService.changePlan(actors.owner, { orgId: org.id, plan: "growth", interval: "annual" });

    await expect(billingService.assertWorkspaceWritable(org.id)).resolves.toBeUndefined();
    await expect(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
    ).resolves.toBeDefined();
  });

  it("lets an owner cancel, which locks from the cancellation date, and delete the workspace", async () => {
    const tenant = await createTenant("lock-cancel", "growth");
    const { org, project, actors } = tenant;

    await billingService.cancelSubscription(actors.owner, { orgId: org.id, cancelImmediately: false });
    // Scheduled for the end of the period: still writable until then.
    await expect(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
    ).resolves.toBeDefined();

    await billingService.cancelSubscription(actors.owner, { orgId: org.id, cancelImmediately: true });
    await expectLocked(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
      "canceled",
    );

    await expect(
      organizationService.deleteOrganization(actors.owner, { orgId: org.id, confirmSlug: org.slug }),
    ).resolves.toMatchObject({ id: org.id });
  });

  it("keeps a member's own notification housekeeping working", async () => {
    const tenant = await createTenant("lock-notifications", "growth");
    const { org, actors, userIds } = tenant;
    setSubscription(org.id, { status: "past_due" });

    await notificationService.notify(org.id, "comment_created", [userIds.member], {
      title: "Hello",
      body: "World",
      href: "/issues/1",
      actorId: userIds.admin,
    });

    await expect(notificationService.markAllRead(actors.member, org.id)).resolves.toBe(1);
    await expect(
      notificationService.updatePreference(actors.member, {
        orgId: org.id,
        userId: userIds.member,
        kind: "comment_created",
        inApp: true,
        email: false,
        digestOnly: false,
      }),
    ).resolves.toMatchObject({ email: false });
  });

  it("keeps Taskflow's own work running: fan-out and the overdue sweep", async () => {
    const ctx = await prepare("lock-background");
    const { org, actors, userIds } = ctx.tenant;
    const overdue = await issueService.createIssue(
      actors.member,
      issueInput(org.id, ctx.tenant.project.id, {
        title: "Late already",
        assigneeId: userIds.member,
        dueAt: "2026-01-01T00:00:00.000Z",
      }),
    );
    setSubscription(org.id, { status: "past_due" });

    const notified: string[] = [];
    const off = subscribe("issue.overdue", (payload) => void notified.push(payload.issueId));
    resetOverdueTracking();

    const result = await runOverdueIssueJob(new Date());
    off();

    expect(result.failed).toBe(0);
    expect(notified).toContain(overdue.id);
    await expect(
      notificationService.listNotifications(actors.member, {
        orgId: org.id,
        recipientId: userIds.member,
        unreadOnly: true,
        limit: 20,
        cursor: null,
      }),
    ).resolves.toMatchObject({ items: expect.arrayContaining([expect.objectContaining({ kind: "issue_overdue" })]) });
  });
});

describe("trial expiry", () => {
  it("moves an ended trial to the free plan, which unlocks the workspace", async () => {
    const tenant = await createTenant("lock-trial-fits", "starter");
    const { org, project, actors, userIds } = tenant;
    const viewer = await memberRepo.findMember(org.id, userIds.viewer);
    if (viewer) await memberRepo.archiveMember(org.id, viewer.id);
    await usageRepo.recomputeUsage(org.id);
    setSubscription(org.id, { status: "trialing", currentPeriodEnd: daysFromNow(-1) });

    await expectLocked(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
      "trial_ended",
    );

    await runTrialExpiryJob(new Date());

    await expect(subscriptionRepo.findSubscription(org.id)).resolves.toMatchObject({
      plan: "free",
      status: "active",
    });
    await expect(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
    ).resolves.toBeDefined();
  });

  it("leaves a workspace that no longer fits the free plan locked until a plan is chosen", async () => {
    // createTenant seeds four members and the free plan allows three seats.
    const tenant = await createTenant("lock-trial-outgrown", "starter");
    const { org, project, actors } = tenant;
    await usageRepo.recomputeUsage(org.id);
    setSubscription(org.id, { status: "trialing", currentPeriodEnd: daysFromNow(-1) });

    await runTrialExpiryJob(new Date());

    await expectLocked(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
      "trial_ended",
    );

    await billingService.changePlan(actors.owner, { orgId: org.id, plan: "starter", interval: "monthly" });
    await expect(
      issueService.createIssue(actors.member, issueInput(org.id, project.id)),
    ).resolves.toBeDefined();
  });

  it("maps a refused write onto plan_limit_exceeded for the client", async () => {
    const tenant = await createTenant("lock-app-error", "growth");
    setSubscription(tenant.org.id, { status: "past_due" });

    const error = await issueService
      .createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id))
      .catch((thrown: unknown) => thrown);

    expect(toAppError(error)).toMatchObject({
      code: "plan_limit_exceeded",
      meta: { reason: "past_due" },
    });
  });
});
